from math import exp,log
from itertools import product
# Enumerate the manuscript's SCM exactly, integrating the shared uniform U1.
p={}
for h,v,c,r,y in product((0,1),repeat=5):
 phv=(1/6 if h==v else 1/3)
 pr=1/(1+exp(-(.75*h+.5*c)))
 py=1/(1+exp(-(-.5+2.5*v+1.75*c)))
 p[h,v,c,r,y]=phv*.5*(pr if r else 1-pr)*(py if y else 1-py)
def cond_y(**given):
 ids={'h':0,'v':1,'c':2,'r':3}
 keep=[(x,q) for x,q in p.items() if all(x[ids[k]]==a for k,a in given.items())]
 return sum(q*x[4] for x,q in keep)/sum(q for x,q in keep)
print('Exact probabilities from the stated simulation SCM:')
for h in (0,1): print(f'P(Y=1 | H={h}) = {cond_y(h=h):.6f}')
for c,r in product((0,1),repeat=2): print(f'P(Y=1 | R={r}, C={c}) = {cond_y(r=r,c=c):.6f}')
