/bin/bash -c "python3 - <<'PY'
from itertools import combinations
obs=['H','V','R','Y']
original=[('U','H'),('U','V'),('H','R'),('C','R'),('C','Y'),('V','Y')]
alternative=[('H','V'),('H','R'),('C','R'),('C','Y'),('V','Y')]
def dsep(edges,a,b,z):
 an=set([a,b])|set(z)
 while True:
  nxt=an|{x for x,y in edges if y in an}
  if nxt==an: break
  an=nxt
 graph={x:set() for x in an}
 for x,y in edges:
  if x in an and y in an: graph[x].add(y);graph[y].add(x)
 for y in an:
  pars=[x for x,t in edges if t==y and x in an]
  for x,w in combinations(pars,2): graph[x].add(w);graph[w].add(x)
 seen=set(z); todo=[a]
 while todo:
  x=todo.pop()
  if x==b: return False
  if x in seen: continue
  seen.add(x);todo.extend(graph[x]-seen)
 return True
signatures=[]
for name,edges in [('original',original),('alternative H causes V',alternative)]:
 ci=[]
 for a,b in combinations(obs,2):
  rem=[x for x in obs if x not in [a,b]]
  for size in range(len(rem)+1):
   for z in combinations(rem,size):
    if dsep(edges,a,b,z): ci.append((a,b,z))
 print(name,ci)
 signatures.append(ci)
print('Same observed conditional independences:',signatures[0]==signatures[1])
PY"

